// PV7 storage-worker: envelope encryption, endpoint (SSRF) checks, and the bucket check and object operations over
// the real handler, a SQLite D1 with every migration applied, and s3rver (an S3-compatible server) on a local port.
// Generated bytes only; the fake credentials are s3rver's fixed test pair.

import { DatabaseSync } from "node:sqlite";
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash, randomBytes } from "node:crypto";
import { D1ApiAdapter } from "@saas/db/runner";
import type { D1Binding } from "@saas/db/d1";
import { aadFor, open, parseKek, seal } from "@storage-worker/envelope";
import { validateBucket, validateSecret } from "@storage-worker/endpoint";
import { CHECK_TIMEOUT_MS, clearRowCache, handle, type Env } from "@storage-worker/index";

const __dirname = dirname(fileURLToPath(import.meta.url));
const MIGRATIONS = resolve(__dirname, "../../..", "packages/db/src/migrations");

function migrated(): DatabaseSync {
  const db = new DatabaseSync(":memory:");
  for (const dir of readdirSync(MIGRATIONS).filter((d) => existsSync(join(MIGRATIONS, d, "up.sql"))).sort()) {
    for (const st of D1ApiAdapter.splitStatements(readFileSync(join(MIGRATIONS, dir, "up.sql"), "utf8"))) db.exec(st);
  }
  return db;
}
function d1Over(db: DatabaseSync): D1Binding {
  return {
    prepare(query: string) {
      let bound: unknown[] = [];
      const st = {
        bind(...v: unknown[]) {
          bound = v;
          return st;
        },
        all<T>() {
          return Promise.resolve({ results: db.prepare(query).all(...(bound as never[])) as T[], success: true });
        },
      };
      return st;
    },
    async batch(sts: Array<{ all(): Promise<unknown> }>) {
      const out = [];
      for (const s of sts) out.push(await s.all());
      return out;
    },
  } as unknown as D1Binding;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const body = async (r: Response): Promise<any> => r.json();
const KEK = "a".repeat(64);
const ORG = "11111111-1111-4111-8111-111111111111";
const LIB = "22222222-2222-4222-8222-222222222222";

describe("envelope encryption", () => {
  it("seals and opens credentials, bound to the backend; a wrong key or another row can't open them", async () => {
    const kek = parseKek(KEK)!;
    const sealed = await seal(kek, { accessKeyId: "AKIAEXAMPLE", secretAccessKey: "secret-value-123" }, aadFor(ORG, LIB, "b1"));
    expect(sealed).not.toContain("secret-value-123");
    expect(sealed).not.toContain("AKIAEXAMPLE");
    expect(await open(kek, sealed, aadFor(ORG, LIB, "b1"))).toEqual({ accessKeyId: "AKIAEXAMPLE", secretAccessKey: "secret-value-123" });
    expect(await open(kek, sealed, aadFor(ORG, LIB, "b2"))).toBeNull();
    expect(await open(parseKek("b".repeat(64))!, sealed, aadFor(ORG, LIB, "b1"))).toBeNull();
    expect(await open(kek, sealed.replace(/"ct":"(.)/, (_m, c: string) => `"ct":"${c === "A" ? "B" : "A"}`), aadFor(ORG, LIB, "b1"))).toBeNull();
    // two seals of the same secret differ (fresh data key and nonces)
    expect(await seal(kek, { accessKeyId: "AKIAEXAMPLE", secretAccessKey: "secret-value-123" }, aadFor(ORG, LIB, "b1"))).not.toBe(sealed);
    expect(parseKek("short")).toBeNull();
  });
});

describe("endpoint checks (SSRF)", () => {
  const base = { region: "auto", bucket: "my-bucket", prefix: "pixvault" };
  it("accept a public https endpoint and normalise the prefix", () => {
    const r = validateBucket({ ...base, endpoint: "https://s3.eu-central-1.amazonaws.com" });
    expect(r).toEqual({ ok: true, value: { endpoint: "https://s3.eu-central-1.amazonaws.com", region: "auto", bucket: "my-bucket", prefix: "pixvault/", pathStyle: false } });
  });
  it.each([
    ["http://s3.example.com", "plain http"],
    ["https://127.0.0.1", "an IPv4 literal"],
    ["https://169.254.169.254", "the metadata address"],
    ["https://[::1]", "an IPv6 literal"],
    ["https://localhost", "localhost"],
    ["https://minio.internal", "an internal name"],
    ["https://nas.local", "a .local name"],
    ["https://metadata.google.internal", "a metadata name"],
    ["https://user:pass@s3.example.com", "user info"],
    ["https://s3.example.com:9000", "an odd port"],
    ["https://s3.example.com/path", "a path"],
    ["not a url", "garbage"],
  ])("refuse %s (%s)", (endpoint) => {
    expect(validateBucket({ ...base, endpoint }).ok).toBe(false);
  });
  it("refuse bad buckets, regions and prefixes, and bound secrets", () => {
    expect(validateBucket({ ...base, endpoint: "https://s3.example.com", bucket: "UPPER" }).ok).toBe(false);
    expect(validateBucket({ ...base, endpoint: "https://s3.example.com", region: "us east" }).ok).toBe(false);
    expect(validateBucket({ ...base, endpoint: "https://s3.example.com", prefix: "../escape" }).ok).toBe(false);
    expect(validateBucket({ ...base, endpoint: "https://s3.example.com", prefix: "/abs" }).ok).toBe(false);
    expect(validateSecret({ accessKeyId: "ab", secretAccessKey: "x" }).ok).toBe(false);
    expect(validateSecret({ accessKeyId: "AKIA1234", secretAccessKey: "long-enough-secret" }).ok).toBe(true);
  });
  it("allow http and local hosts only in test mode", () => {
    expect(validateBucket({ ...base, endpoint: "http://127.0.0.1:9000" }, true).ok).toBe(true);
  });
});

describe("storage-worker against an S3-compatible server", () => {
  let server: { run(): Promise<{ port: number }>; close(): Promise<void> };
  let dir: string;
  let endpoint: string;
  let db: DatabaseSync;
  let env: Env;

  beforeAll(async () => {
    dir = mkdtempSync(join(tmpdir(), "pv-sw-"));
    const S3rver = (await import("s3rver")).default as unknown as new (o: Record<string, unknown>) => typeof server;
    server = new S3rver({ port: 0, address: "127.0.0.1", silent: true, directory: dir, configureBuckets: [{ name: "byo" }] });
    endpoint = `http://127.0.0.1:${(await server.run()).port}`;
  });
  afterAll(async () => {
    await server?.close();
    rmSync(dir, { recursive: true, force: true });
  });
  beforeEach(() => {
    db = migrated();
    env = { ENVIRONMENT: "test", PLATFORM_DB: d1Over(db) as unknown as D1Database, STORAGE_KEK: KEK, ALLOW_TEST_ENDPOINTS: "true" };
    clearRowCache();
  });

  const post = (path: string, body: unknown) => handle(new Request(`https://storage.internal${path}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }), env);
  const bucket = (extra: Record<string, unknown> = {}) => ({ endpoint, region: "us-east-1", bucket: "byo", prefix: "team-a", pathStyle: true, accessKeyId: "S3RVER", secretAccessKey: "S3RVER", ...extra });

  it("a bucket check writes, reads, lists and deletes a test object under the prefix", async () => {
    const r = await post("/v1/storage/check", bucket());
    const res = (await r.json()) as { data: { ok: boolean; steps: { step: string; ok: boolean }[] } };
    expect(res.data.ok).toBe(true);
    expect(res.data.steps.map((s) => s.step)).toEqual(["put", "head", "get", "list", "delete"]);
    const missing = await body(await post("/v1/storage/check", bucket({ bucket: "nope-bucket" })));
    expect(missing.data).toMatchObject({ ok: false, steps: [{ step: "put", ok: false, code: "NoSuchBucket" }] });
  });

  it("stores a backend with sealed credentials, then runs object operations only under its prefix", async () => {
    const created = await post("/v1/storage/backends", { orgId: ORG, libraryId: LIB, ...bucket() });
    expect(created.status).toBe(201);
    const { backend } = ((await created.json()) as { data: { backend: { id: string; prefix: string; status: string } } }).data;
    expect(backend).toMatchObject({ prefix: "team-a/", status: "active" });
    expect(JSON.stringify(backend)).not.toContain("S3RVER");
    const row = db.prepare(`SELECT credential_ref FROM media_storage_backends WHERE id = ?`).get(backend.id) as { credential_ref: string };
    expect(row.credential_ref).not.toContain("S3RVER");

    const q = (key: string, extra: Record<string, string> = {}) => `/v1/storage/objects?${new URLSearchParams({ orgId: ORG, libraryId: LIB, backendId: backend.id, key, ...extra })}`;
    const bytes = randomBytes(2048);
    const sha = createHash("sha256").update(bytes).digest("hex");
    const put = await handle(new Request(`https://storage.internal${q("team-a/blob/x", { sha256: sha })}`, { method: "PUT", body: bytes }), env);
    expect(put.status).toBe(200);
    // a wrong hash is refused before anything is sent
    const bad = await handle(new Request(`https://storage.internal${q("team-a/blob/y", { sha256: "0".repeat(64) })}`, { method: "PUT", body: bytes }), env);
    expect(bad.status).toBe(422);
    expect((await body(await handle(new Request(`https://storage.internal${q("team-a/blob/y", { op: "head" })}`), env))).error.code).toBe("not_found");
    const got = await handle(new Request(`https://storage.internal${q("team-a/blob/x")}`, { headers: { range: "bytes=0-9" } }), env);
    expect(Buffer.from(await got.arrayBuffer()).equals(bytes.subarray(0, 10))).toBe(true);
    expect((await body(await handle(new Request(`https://storage.internal${q("team-a/blob/x", { op: "head" })}`), env))).data).toMatchObject({ size: 2048 });

    // outside the prefix, walking out of it, another library's scope: 404, never touched
    expect((await handle(new Request(`https://storage.internal${q("other/blob/x")}`), env)).status).toBe(404);
    expect((await handle(new Request(`https://storage.internal${q("team-a/../other/x")}`), env)).status).toBe(404);
    const otherLib = `/v1/storage/objects?${new URLSearchParams({ orgId: ORG, libraryId: "33333333-3333-4333-8333-333333333333", backendId: backend.id, key: "team-a/blob/x" })}`;
    expect((await handle(new Request(`https://storage.internal${otherLib}`), env)).status).toBe(404);

    // multipart through the worker
    const id = ((await body(await handle(new Request(`https://storage.internal${q("team-a/blob/big", { op: "createMultipart" })}`, { method: "POST" }), env))) as { data: { uploadId: string } }).data.uploadId;
    const p1 = randomBytes(5 * 1024 * 1024);
    const r1 = (await body(await handle(new Request(`https://storage.internal${q("team-a/blob/big", { op: "uploadPart", uploadId: id, partNumber: "1" })}`, { method: "PUT", body: p1 }), env))).data;
    const done = await handle(new Request(`https://storage.internal${q("team-a/blob/big", { op: "completeMultipart" })}`, { method: "POST", body: JSON.stringify({ uploadId: id, parts: [r1] }) }), env);
    expect(done.status).toBe(200);
    expect((await body(await handle(new Request(`https://storage.internal${q("team-a/blob/big", { op: "head" })}`), env))).data.size).toBe(p1.length);

    const del = await handle(new Request(`https://storage.internal${q("team-a/blob/x")}`, { method: "DELETE" }), env);
    expect(del.status).toBe(200);
    expect((await handle(new Request(`https://storage.internal${q("team-a/blob/x", { op: "head" })}`), env)).status).toBe(404);
  });

  it("a backend that stops working shows error with the S3 code, and recovers", async () => {
    const created = await post("/v1/storage/backends", { orgId: ORG, libraryId: LIB, ...bucket() });
    const id = ((await created.json()) as { data: { backend: { id: string } } }).data.backend.id;
    // the bucket moves away: point the row at a bucket that doesn't exist
    db.prepare(`UPDATE media_storage_backends SET bucket = 'gone-bucket' WHERE id = ?`).run(id);
    const check = await body(await post("/v1/storage/backends/check", { orgId: ORG, libraryId: LIB, backendId: id }));
    expect(check.data).toMatchObject({ ok: false });
    expect(db.prepare(`SELECT status, last_error FROM media_storage_backends WHERE id = ?`).get(id)).toEqual({ status: "error", last_error: "NoSuchBucket" });
    db.prepare(`UPDATE media_storage_backends SET bucket = 'byo' WHERE id = ?`).run(id);
    await post("/v1/storage/backends/check", { orgId: ORG, libraryId: LIB, backendId: id });
    expect(db.prepare(`SELECT status, last_error FROM media_storage_backends WHERE id = ?`).get(id)).toEqual({ status: "active", last_error: null });
  });

  it("a server that never answers times out with a code, not a hang", async () => {
    const hang = (_u: RequestInfo | URL, init?: RequestInit) =>
      new Promise<Response>((_res, rej) => init?.signal?.addEventListener("abort", () => rej(init.signal!.reason)));
    const r = await handle(new Request("https://storage.internal/v1/storage/check", { method: "POST", body: JSON.stringify(bucket()) }), env, { fetch: hang as typeof fetch, timeoutMs: 50 });
    expect((await body(r)).data).toMatchObject({ ok: false, steps: [{ step: "put", ok: false, code: "Timeout" }] });
    expect(CHECK_TIMEOUT_MS).toBe(15_000);
  });

  it("a failing bucket isn't stored; a missing key makes the worker refuse to store anything", async () => {
    const r = await post("/v1/storage/backends", { orgId: ORG, libraryId: LIB, ...bucket({ bucket: "nope-bucket" }) });
    expect(r.status).toBe(409);
    expect(db.prepare(`SELECT COUNT(*) AS n FROM media_storage_backends WHERE kind = 's3-compatible'`).get()).toEqual({ n: 0 });
    delete env.STORAGE_KEK;
    expect((await post("/v1/storage/backends", { orgId: ORG, libraryId: LIB, ...bucket() })).status).toBe(503);
    expect(await body(await handle(new Request("https://storage.internal/health"), env))).toMatchObject({ kek: false });
  });
});
